def transform(grid):
    out = [row[:] for row in grid]
    cells = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 5]
    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)

    height, width = r1 - r0 - 1, c1 - c0 - 1
    layers = max(0, (min(height, width) - 3) // 2)
    for k in range(1, layers + 1):
        color = 2 if k % 2 else 5
        top, bottom = r0 + k, r1 - k
        left, right = c0 + k, c1 - k
        for c in range(left, right + 1):
            out[top][c] = out[bottom][c] = color
        for r in range(top, bottom + 1):
            out[r][left] = out[r][right] = color

    # For an even-sized interior, the last remaining center is filled in 5.
    remaining_h = height - 2 * layers
    remaining_w = width - 2 * layers
    if remaining_h == remaining_w and remaining_h > 0 and remaining_h % 2 == 0:
        for r in range(r0 + layers + 1, r1 - layers):
            for c in range(c0 + layers + 1, c1 - layers):
                out[r][c] = 5
    return out
